//! Negotiation prep — the case for the phone call, assembled from your own data.
//!
//! Issuers reduce rates, waive fees and open hardship plans routinely, and almost nobody asks. The
//! call costs nothing: a retention conversation is not a credit application, so there is no hard
//! pull and no score consequence to trying. What there IS, is a right ask and a wrong one — and
//! getting that wrong is how a call that could have helped ends with a "no" on the record.
//!
//! # The ask depends on whether you can pay
//!
//! This is the judgement the module exists to make:
//!
//! - **You can pay** → a RATE REDUCTION, on the strength of tenure, a clean payment history, and a
//!   competing offer you can actually name. This is a customer worth keeping asking to be treated
//!   like one.
//! - **You cannot pay** → a HARDSHIP PLAN, and the timing is the whole thing: entered BEFORE a
//!   missed payment it is an arrangement, and the account stays current on the report. Entered
//!   after, the delinquency is already reported and cannot be taken back. Asking for a rate cut in
//!   this situation wastes the one call you get.
//!
//! A fee that has already landed is a SEPARATE, EASIER call. First-offence waivers are close to
//! routine, so a recent fee is its own ask and goes first — the cheapest win available, and it does
//! not spend any of the goodwill the rate call needs.
//!
//! The evidence here is only ever what the data actually supports. ABSENT EVIDENCE IS ABSENT: a case
//! that invents leverage produces a person confidently saying something an issuer can disprove from
//! their own screen, which is worse than saying nothing.
use crate::fees::{FeeAudit, FeeKind};
use crate::money::{money, scale, Money, Rounding};
use crate::position::Position;
use crate::transfer::TransferOffer;
use crate::txn::days_between;

pub(crate) use pct::pct;
pub use utilisation_if_closed::utilisation_if_closed;
pub(crate) use gather_evidence::gather_evidence;
pub use total_if_every_ask_lands::total_if_every_ask_lands;
pub use call_order::call_order;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ask {
    FeeWaiver,
    RateReduction,
    HardshipPlan,
}

impl Ask {
    pub fn label(self) -> &'static str {
        match self {
            Ask::FeeWaiver => "fee-waiver",
            Ask::RateReduction => "rate-reduction",
            Ask::HardshipPlan => "hardship-plan",
        }
    }

    /// Cheapest win first. A waiver call does not spend the goodwill the rate call needs.
    fn rank(self) -> u8 {
        match self {
            Ask::FeeWaiver => 0,
            Ask::HardshipPlan => 1,
            Ask::RateReduction => 2,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Strength {
    Strong,
    Moderate,
    Weak,
}

impl Strength {
    pub fn label(self) -> &'static str {
        match self {
            Strength::Strong => "strong",
            Strength::Moderate => "moderate",
            Strength::Weak => "weak",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Evidence {
    /// What can actually be SAID on the call.
    pub claim: String,
    pub strength: Strength,
    /// Where it came from, so it can be checked before it is repeated to a stranger.
    pub source: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct NegotiationCase {
    pub account: String,
    pub institution: String,
    pub ask: Ask,
    /// Why THIS ask and not another.
    pub why: String,
    pub evidence: Vec<Evidence>,
    /// Things not to say, each with the reason it costs you.
    pub do_not_say: Vec<String>,
    /// What a reasonable outcome looks like, so a partial win is not read as a failure.
    pub realistic: String,
    /// A year of the ask, IF it is granted. Contingent, and labelled as such.
    pub annual_value_if_won: Money,
    pub urgency: Option<String>,
}

pub struct NegotiationInput<'a> {
    pub position: &'a Position,
    /// `YYYY-MM-DD`. Passed in, never read from a clock.
    pub as_of: &'a str,
    /// Whether the runway holds — the single fact that decides the ask.
    pub can_pay: bool,
    pub fees: Option<&'a FeeAudit>,
    /// Real offers you could name on the call. The strongest lever there is.
    pub offers: &'a [TransferOffer],
    /// Months the account has been open, where it is known.
    pub tenure_months: &'a [(String, i64)],
    /// How much of a rate cut to model. Not a promise, a unit for the arithmetic.
    pub target_reduction: f64,
    /// A fee this recent is a live waiver candidate.
    pub fee_window_days: i64,
    /// Utilisation above which closing this line would hurt the rest.
    pub utilisation_concern: f64,
}

impl<'a> NegotiationInput<'a> {
    pub fn new(position: &'a Position, as_of: &'a str, can_pay: bool) -> Self {
        NegotiationInput {
            position,
            as_of,
            can_pay,
            fees: None,
            offers: &[],
            tenure_months: &[],
            target_reduction: 0.05,
            fee_window_days: 120,
            utilisation_concern: 0.3,
        }
    }
}

pub fn prepare_negotiation(input: &NegotiationInput) -> Vec<NegotiationCase> {
    let currency = input.position.currency;
    let mut cases: Vec<NegotiationCase> = Vec::new();

    for a in &input.position.accounts {
        let (true, Some(owed)) = (a.is_debt, a.owed) else { continue };

        let evidence = gather_evidence(a, input);
        let recent_fees: Vec<&crate::fees::Fee> = input
            .fees
            .map(|f| f.fees.as_slice())
            .unwrap_or(&[])
            .iter()
            .filter(|f| {
                f.account == a.account
                    && f.kind != FeeKind::Interest
                    && days_between(&f.date, input.as_of) <= input.fee_window_days
                    && days_between(&f.date, input.as_of) >= 0
            })
            .collect();

        let mut do_not_say: Vec<String> = Vec::new();
        if let Some(closed) = utilisation_if_closed(input.position, &a.account) {
            if closed > input.utilisation_concern {
                // THEY MIGHT SAY YES. The balance moves nowhere and the limit disappears.
                do_not_say.push(format!(
                    "do not threaten to close this account — if they accept, utilisation across everything left goes to {}%, and the balance has not moved an inch",
                    (closed * 100.0).round()
                ));
            }
        }
        do_not_say.push("do not say you are considering bankruptcy unless you are — it can freeze the account and end the conversation you wanted".to_string());
        do_not_say.push("do not accept a deferral that CAPITALISES the interest without asking what it does to the balance".to_string());

        // THE CHEAPEST WIN FIRST.
        if !recent_fees.is_empty() {
            let total: i64 = recent_fees.iter().map(|f| f.amount.minor.abs()).sum();
            cases.push(NegotiationCase {
                account: a.account.clone(),
                institution: a.institution.clone(),
                ask: Ask::FeeWaiver,
                why: format!(
                    "{} fee(s) totalling {total} minor units landed in the last {} days, and a first-offence waiver is close to routine for anyone who asks",
                    recent_fees.len(),
                    input.fee_window_days
                ),
                evidence: evidence.clone(),
                do_not_say: do_not_say.clone(),
                realistic: "one fee waived is the usual outcome; several at once is not. Ask for the most recent one by name and date.".to_string(),
                annual_value_if_won: money(total, currency),
                urgency: Some("fees are easiest to reverse in the cycle they appear — this gets harder every statement that passes".to_string()),
            });
        }

        if !input.can_pay {
            // THE TIMING IS THE WHOLE THING.
            let mut dns = do_not_say.clone();
            dns.push("do not ask for a rate reduction in the same call — it signals you expect to keep revolving, and it is answered by a different team".to_string());
            cases.push(NegotiationCase {
                account: a.account.clone(),
                institution: a.institution.clone(),
                ask: Ask::HardshipPlan,
                why: "the runway does not hold, so a rate cut is not the ask — a hardship or forbearance arrangement is, and it is a different department and a different conversation".to_string(),
                evidence,
                do_not_say: dns,
                realistic: "a fixed reduced rate for 6-12 months with the account reported CURRENT is a normal outcome; a written-off balance is not".to_string(),
                annual_value_if_won: scale(owed, a.apr.unwrap_or(0.0).min(0.15), Rounding::HalfUp),
                urgency: Some(
                    "CALL BEFORE A PAYMENT IS MISSED. Entered before a delinquency this is an arrangement and the account stays current on the report; entered after, the delinquency is already reported and no arrangement takes it back.".to_string(),
                ),
            });
            continue;
        }

        let strong = evidence.iter().filter(|e| e.strength == Strength::Strong).count();
        cases.push(NegotiationCase {
            account: a.account.clone(),
            institution: a.institution.clone(),
            ask: Ask::RateReduction,
            // The call costing nothing is true either way, so it is said either way. It is the
            // reason to make the WEAK call as well as the strong one, and burying it in the strong
            // branch would leave a case with no evidence reading as a case not worth making.
            why: if strong > 0 {
                format!("{strong} piece(s) of strong evidence support it. The call costs nothing — a retention conversation is not a credit application, so there is no hard pull.")
            } else {
                "there is little here to argue from, so this is a plain ask rather than a case. The call still costs nothing — a retention conversation is not a credit application, so there is no hard pull — and the answer is sometimes yes anyway.".to_string()
            },
            evidence,
            do_not_say,
            realistic: format!(
                "a reduction of 3-7 points is a normal outcome; {} going to zero is not. A \"no\" today does not stop you asking again in six months.",
                pct(a.apr.unwrap_or(0.0))
            ),
            annual_value_if_won: scale(owed, input.target_reduction.min(a.apr.unwrap_or(0.0)), Rounding::HalfUp),
            urgency: None,
        });
    }

    // Cheapest win first, then by what the ask is worth.
    cases.sort_by(|x, y| x.ask.rank().cmp(&y.ask.rank()).then_with(|| y.annual_value_if_won.minor.cmp(&x.annual_value_if_won.minor)));
    cases
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::Currency;
    use crate::position::AccountPosition;
    use crate::fees::audit_fees;
    use crate::money::usd;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY.
    #[allow(clippy::too_many_arguments)]
    fn acct(account: &str, inst: &str, owed: i64, apr: Option<f64>, limit: Option<i64>, util: Option<f64>) -> AccountPosition {
        AccountPosition {
            account: account.to_string(),
            institution: inst.to_string(),
            kind: Kind::Credit,
            balance: usd(-owed),
            as_of: "2026-06-30".to_string(),
            rolled_forward: 0,
            is_debt: true,
            owed: Some(usd(owed)),
            credit_limit: limit.map(usd),
            available: None,
            utilisation: util,
            apr,
            daily_interest: None,
            minimum_payment: None,
        }
    }

    fn pos(accounts: Vec<AccountPosition>) -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts,
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(0),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete: true,
            provenance: "x".to_string(),
            problems: Vec::new(),
        }
    }

    fn t(date: &str, d: &str, m: i64, a: &str) -> Txn {
        Txn { account: a.to_string(), date: date.to_string(), description: d.to_string(), amount: usd(m) }
    }

    fn two_cards() -> Position {
        pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), Some(0.6)), acct("store", "storeco", 80_000, Some(0.0999), Some(100_000), Some(0.8))])
    }

    fn fee_audit() -> FeeAudit {
        audit_fees(
            &[t("2026-05-20", "LATE FEE", -3_500, "visa"), t("2026-01-05", "INTEREST CHARGE", -4_500, "visa"), t("2026-02-05", "INTEREST CHARGE", -4_300, "visa")],
            Currency::USD,
        )
    }

    fn offers() -> Vec<TransferOffer> {
        vec![TransferOffer {
            id: "o1".into(),
            institution: "newbank".into(),
            promo_apr: 0.0,
            promo_months: 12,
            transfer_fee_rate: 0.03,
            transfer_fee_min: None,
            go_to_apr: 0.2999,
            credit_limit: None,
            offer_expires: Some("2026-09-01".into()),
        }]
    }

    #[test]
    fn closing_the_line_is_the_advice_that_backfires_if_they_say_yes() {
        let p = two_cards();
        // Closing the visa removes a 500000 limit and moves NO balance: 380000 owed against the
        // 100000 that is left is 380%. That is why "I'll close it" is a threat you must not make.
        assert_eq!(utilisation_if_closed(&p, "visa"), Some(3.8));
        assert_eq!(utilisation_if_closed(&p, "store"), Some(0.76));
        // With only one line there is no remaining limit to divide by — ABSENT, not zero.
        assert_eq!(utilisation_if_closed(&pos(vec![acct("a", "a", 100, Some(0.1), Some(1_000), None)]), "a"), None);
    }

    #[test]
    fn being_able_to_pay_asks_for_a_rate_and_not_being_able_to_asks_for_hardship() {
        let p = two_cards();
        let f = fee_audit();
        let o = offers();
        let tenure = [("visa".to_string(), 48i64), ("store".to_string(), 6i64)];
        let can = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        let cannot = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", false) });
        assert_eq!(can.iter().map(|c| c.ask.label()).collect::<Vec<_>>(), vec!["fee-waiver", "rate-reduction", "rate-reduction"]);
        assert_eq!(cannot.iter().map(|c| c.ask.label()).collect::<Vec<_>>(), vec!["fee-waiver", "hardship-plan", "hardship-plan"]);
        // Asking for a rate cut when you cannot pay wastes the one call you get, so it is not
        // offered AND the reason is said in the same breath.
        assert!(cannot[1].do_not_say.iter().any(|d| d.contains("do not ask for a rate reduction in the same call")));
        assert!(cannot[1].urgency.as_ref().unwrap().contains("CALL BEFORE A PAYMENT IS MISSED"));
    }

    #[test]
    fn the_cheapest_win_goes_first_because_it_does_not_spend_the_goodwill() {
        let p = two_cards();
        let f = fee_audit();
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(cases[0].ask, Ask::FeeWaiver);
        assert_eq!(cases[0].annual_value_if_won.minor, 3_500);
        assert!(cases[0].urgency.as_ref().unwrap().contains("harder every statement that passes"));
        // Then by what the ask is worth: visa 15000 before store 4000.
        assert_eq!(cases.iter().skip(1).map(|c| c.annual_value_if_won.minor).collect::<Vec<_>>(), vec![15_000, 4_000]);
    }

    #[test]
    fn an_interest_row_is_not_a_waiver_candidate_and_an_old_fee_is_not_recent() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), None)]);
        // Interest is excluded by KIND — it is the cost of the balance, not a fee to reverse.
        let interest_only = audit_fees(&[t("2026-05-20", "INTEREST CHARGE", -4_500, "visa")], Currency::USD);
        let a = prepare_negotiation(&NegotiationInput { fees: Some(&interest_only), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(a.iter().all(|c| c.ask != Ask::FeeWaiver));
        // And a fee outside the window is not a live candidate either.
        let old = audit_fees(&[t("2025-05-20", "LATE FEE", -3_500, "visa")], Currency::USD);
        let b = prepare_negotiation(&NegotiationInput { fees: Some(&old), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(b.iter().all(|c| c.ask != Ask::FeeWaiver));
        // A fee dated in the FUTURE is not one either — days_between would be negative.
        let future = audit_fees(&[t("2026-12-20", "LATE FEE", -3_500, "visa")], Currency::USD);
        let c = prepare_negotiation(&NegotiationInput { fees: Some(&future), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(c.iter().all(|x| x.ask != Ask::FeeWaiver));
    }

    #[test]
    fn absent_evidence_is_absent_and_the_call_is_still_worth_making() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        let cases = prepare_negotiation(&NegotiationInput::new(&p, "2026-06-30", true));
        assert_eq!(cases.len(), 1);
        // NO invented leverage. A case that fabricates evidence produces somebody confidently
        // saying something an issuer can disprove from their own screen.
        assert!(cases[0].evidence.is_empty());
        assert!(cases[0].why.contains("this is a plain ask rather than a case"));
        // And the reason to call anyway is still stated — a case with no evidence must not read as
        // a case not worth making.
        assert!(cases[0].why.contains("The call still costs nothing"));
        assert_eq!(cases[0].annual_value_if_won.minor, 15_000, "5% of 300000, the target reduction");
    }

    #[test]
    fn a_clean_payment_history_is_the_strongest_card_and_people_forget_they_hold_it() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), Some(0.2))]);
        let f = audit_fees(&[t("2026-01-05", "INTEREST CHARGE", -4_500, "visa")], Currency::USD);
        let tenure = [("visa".to_string(), 48i64)];
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        let claims: Vec<(&str, &str)> = cases[0].evidence.iter().map(|e| (e.strength.label(), e.claim.as_str())).collect();
        assert_eq!(claims.len(), 4);
        assert_eq!(claims[1], ("strong", "no late or returned-payment fee appears anywhere in the statements held"));
        assert!(claims[2].1.contains("4500 minor units of interest have been paid"), "their own number");
        assert_eq!(claims[3].0, "moderate", "20% used is a low-risk customer");
        assert!(cases[0].why.starts_with("3 piece(s) of strong evidence"));
    }

    #[test]
    fn under_a_year_is_a_trial_period_rather_than_tenure() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        for (months, want) in [(48i64, "strong"), (12, "moderate"), (11, "weak"), (6, "weak")] {
            let tenure = [("visa".to_string(), months)];
            let cases = prepare_negotiation(&NegotiationInput { tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
            assert_eq!(cases[0].evidence[0].strength.label(), want, "{months} months");
        }
    }

    #[test]
    fn only_an_offer_you_could_actually_take_counts_as_leverage() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        // An offer from the SAME institution is not leverage against that institution.
        let same = vec![TransferOffer { institution: "chase".into(), ..offers()[0].clone() }];
        let a = prepare_negotiation(&NegotiationInput { offers: &same, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(a[0].evidence.is_empty());
        // Nor is an offer at a WORSE rate than the one you already have.
        let worse = vec![TransferOffer { promo_apr: 0.30, ..offers()[0].clone() }];
        let b = prepare_negotiation(&NegotiationInput { offers: &worse, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(b[0].evidence.is_empty());
        // A real, better one is — and it is named with its expiry so it can be checked first.
        let o = offers();
        let c = prepare_negotiation(&NegotiationInput { offers: &o, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(c[0].evidence[0].claim, "newbank is offering 0% for 12 months, expiring 2026-09-01");
        assert!(c[0].evidence[0].source.contains("name it only if it is real and you would take it"));
    }

    #[test]
    fn the_hardship_value_is_capped_because_nobody_is_offered_a_zero_rate() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        let cases = prepare_negotiation(&NegotiationInput::new(&p, "2026-06-30", false));
        // min(apr, 0.15) of the balance — the arithmetic models a plausible outcome rather than the
        // whole rate going away.
        assert_eq!(cases[0].annual_value_if_won.minor, 45_000);
        // And a rate BELOW the cap is not inflated up to it.
        let low = pos(vec![acct("store", "storeco", 80_000, Some(0.0999), None, None)]);
        let c2 = prepare_negotiation(&NegotiationInput::new(&low, "2026-06-30", false));
        assert_eq!(c2[0].annual_value_if_won.minor, 7_992);
    }

    #[test]
    fn the_totals_and_the_call_script_come_out_in_the_order_to_use_them() {
        let p = two_cards();
        let f = fee_audit();
        let o = offers();
        let tenure = [("visa".to_string(), 48i64), ("store".to_string(), 6i64)];
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(total_if_every_ask_lands(&cases, Currency::USD).minor, 22_500, "CONTINGENT — if every one lands");
        let script = call_order(&cases);
        assert_eq!(script.len(), 3);
        assert!(script[0].starts_with("chase: \"I saw a fee on my last statement"));
        assert!(script[1].contains("I've been a customer a while"));
        assert!(script[2].starts_with("storeco:"));
    }

    #[test]
    fn an_account_with_nothing_owed_has_nothing_to_negotiate() {
        let mut a = acct("visa", "chase", 0, Some(0.2299), Some(500_000), None);
        a.owed = None;
        assert!(prepare_negotiation(&NegotiationInput::new(&pos(vec![a]), "2026-06-30", true)).is_empty());
    }
}
